    (src/'CITATION_AUDIT.json').write_text(json.dumps(audit,indent=2));(src/'CITATION_AUDIT.md').write_text('# NOT_APPLICABLE\n\nNo BibTeX/LaTeX sources in this manuscript pipeline. The separately disclosed source/context ledger is not this skill’s cross-model certificate.\n')
